 let a=lsT(X[0],128,'a b s',{fs:22,fill:LSG,m:1})+lsT(X[1]+20,128,'expected',{fs:22,fill:LSG,a:'middle'})+`<line x1="34" y1="142" x2="606" y2="142" stroke="${LSAX}" stroke-width="2"/>`;
 V.forEach((v,i)=>{a+=lsT(X[0],R[i],v,{fs:26,m:1,fw:800})+lsT(X[1]+20,R[i],String(E[i]),{fs:28,a:'middle',m:1,fw:800,fill:BLU})});
