/* ---- this lesson's own icons: the hook picture and the three recap pictures ---- */
function EXTRA(R,ICON){
 /* hook: the mux equation with the wrong letter, a clean compile, and the four checks (y = a: vectors 2 and 4 fail) */
 ICON.lsHook=(x,y)=>{const code='assign y = (~s &amp; a) | (s &amp; a);',x0=x-212,cw=.6*22;
  let s=lsBox(x-230,y-200,460,96,{fill:WHT,st:INK,rx:12})+`<text x="${x0}" y="${y-142}" ${LSM} font-size="22" font-weight="700" fill="${INK}" textLength="${31*cw}" lengthAdjust="spacingAndGlyphs">${code}</text>`+
   `<circle cx="${x0+28.5*cw}" cy="${y-149}" r="17" fill="none" stroke="${RED}" stroke-width="4"/>`+lsT(x-212,y-116,'should be b',{fs:22,fill:RED,fw:800});
  s+=lsBox(x-150,y-80,300,52,{fill:'#E2F4EC',st:GRN,rx:26})+lsT(x,y-44,'compiled: 0 errors',{fs:24,a:'middle',fill:GRN,fw:800});
  [['vector 1','ok',GRN],['vector 2','FAIL',RED],['vector 3','ok',GRN],['vector 4','FAIL',RED]].forEach(([v,r,col],i)=>{const yy=y+12+i*48;
   s+=lsT(x-130,yy,v,{fs:26,m:1})+lsT(x+90,yy,r,{fs:26,m:1,fw:800,fill:col})});
  return s+lsT(x,y+212,'1 0 0 1 expected, 1 1 0 0 out',{fs:22,a:'middle',fill:LSG,m:1})};
 /* recap 1: vector in, DUT, compare with the golden value, PASS */
 ICON.lsTb=(x,y)=>lsBox(x-210,y-150,130,60,{fill:'#E6E9FB',st:BLU,rx:10})+lsT(x-145,y-112,'1 0 1',{fs:24,a:'middle',m:1,fw:800})+lsAr(x-78,y-120,x-38,y-120)+
  lsBox(x-34,y-150,110,60,{fill:WHT,st:INK,rx:10})+lsT(x+21,y-112,'DUT',{fs:26,a:'middle',fw:800})+lsAr(x+78,y-120,x+118,y-120)+lsT(x+124,y-112,'y = 0',{fs:24,m:1,fw:800})+
  lsT(x-210,y-30,'wait #10, then',{fs:24,fill:LSG})+lsT(x-210,y+12,'y === expected 0',{fs:24,m:1,fw:800})+
  lsBox(x-110,y+44,220,70,{fill:'#E2F4EC',st:GRN,rx:12})+lsT(x,y+92,'PASS',{fs:36,a:'middle',fw:800,fill:GRN});
 /* recap 2: the PLA programming table drawn as term lines and output columns: AB feeds both outputs */
 ICON.lsPla=(x,y)=>{let s='';const T=[['AB',y-90,[1,1]],['AC′',y+10,[1,0]],['BC',y+110,[0,1]]],F=[x+40,x+150];
  F.forEach((fx,j)=>{s+=`<line x1="${fx}" y1="${y-130}" x2="${fx}" y2="${y+150}" stroke="${ORG}" stroke-width="4"/>`+lsT(fx,y+188,'F'+(j+1),{fs:28,a:'middle',fw:800,fill:ORG})});
  T.forEach(([n,ty,use],i)=>{s+=lsT(x-210,ty+10,n,{fs:30,m:1,fw:800})+`<line x1="${x-120}" y1="${ty}" x2="${x+200}" y2="${ty}" stroke="${i?BLU:GRN}" stroke-width="${i?4:6}"/>`;
   use.forEach((on,j)=>{if(on)s+=`<circle cx="${F[j]}" cy="${ty}" r="14" fill="${i?BLU:GRN}"/>`})});
  return s+lsT(x-210,y-150,'shared: AB',{fs:26,fw:800,fill:GRN})};
 /* recap 3: the 16 bits of the worked example's LUT, address 13 marked */
 ICON.lsLut=(x,y)=>{let s='';LS_F.forEach((v,i)=>{const cx=x-145+(i%4)*74,cy=y-158+Math.floor(i/4)*74,hot=i===13;
   s+=lsBox(cx,cy,66,66,{fill:hot?'#E6E9FB':(v?'#E2F4EC':WHT),st:hot?BLU:(v?GRN:LSAX),sw:hot?4:2,rx:8})+lsT(cx+33,cy+44,String(v),{fs:30,a:'middle',m:1,fw:800})});
  return s+lsT(x,y+180,'2⁴ = 16 bits',{fs:30,a:'middle',fw:800,fill:GRN})};
}
